document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("mean-form"),t=document.getElementById("mean-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=document.getElementById("mean-input").value.split(",").map(e=>parseFloat(e.trim())).filter(e=>!isNaN(e));if(0===n.length)return t.textContent="Please enter at least one number separated by commas.",void 0;const a=n.reduce((e,t)=>e+t,0)/n.length;t.innerHTML=`<b>Arithmetic Mean:</b> ${a.toFixed(4)}`})});